import { useState, useEffect, useCallback } from 'react';
import { ethers } from 'ethers';
import { getContractAddress, SUPPORTED_CHAIN_IDS, ContractArtifact } from '../contracts/contractConfig';
import { EventData, TicketData, ResaleListing, TransactionState } from '../types';
import toast from 'react-hot-toast';

// Dynamically import the contract artifact (generated by deploy script)
async function loadArtifact(): Promise<ContractArtifact | null> {
  try {
    const mod = await import('../contracts/EventTicketing.json');
    const artifact = mod.default as ContractArtifact;
    // If ABI is empty, the contracts haven't been deployed yet
    if (!artifact.abi || artifact.abi.length === 0) return null;
    return artifact;
  } catch {
    console.warn('EventTicketing.json not found. Run the deploy script first.');
    return null;
  }
}

export function useContract(signer: ethers.JsonRpcSigner | null, chainId: number | null) {
  const [contract, setContract] = useState<ethers.Contract | null>(null);
  const [contractAddress, setContractAddress] = useState<string>('');
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    async function init() {
      if (!signer || !chainId) {
        setContract(null);
        return;
      }

      if (!SUPPORTED_CHAIN_IDS.includes(chainId)) {
        setContract(null);
        return;
      }

      const artifact = await loadArtifact();
      if (!artifact) return;

      const addr = getContractAddress(artifact, chainId);

      if (!addr) {
        console.warn(`No contract address for chainId ${chainId}. Set VITE_CONTRACT_ADDRESS in .env`);
        return;
      }

      setContractAddress(addr);
      const c = new ethers.Contract(addr, artifact.abi as ethers.InterfaceAbi, signer);
      setContract(c);
    }
    init();
  }, [signer, chainId]);

  // ─── Read Functions ────────────────────────────────────────────────────────

  const getEvent = useCallback(async (eventId: bigint): Promise<EventData | null> => {
    if (!contract) return null;
    try {
      const ev = await contract.getEventDetails(eventId);
      return ev as EventData;
    } catch (err) {
      console.error('getEvent error:', err);
      return null;
    }
  }, [contract]);

  const getAllEvents = useCallback(async (): Promise<EventData[]> => {
    if (!contract) return [];
    try {
      const total = await contract.getTotalEvents() as bigint;
      const events: EventData[] = [];
      for (let i = 0n; i < total; i++) {
        try {
          const ev = await contract.getEventDetails(i);
          events.push(ev as EventData);
        } catch {
          // skip invalid
        }
      }
      return events;
    } catch (err) {
      console.error('getAllEvents error:', err);
      return [];
    }
  }, [contract]);

  const getTicket = useCallback(async (tokenId: bigint): Promise<TicketData | null> => {
    if (!contract) return null;
    try {
      const tkt = await contract.getTicketDetails(tokenId);
      return tkt as TicketData;
    } catch (err) {
      console.error('getTicket error:', err);
      return null;
    }
  }, [contract]);

  const getMyTickets = useCallback(async (address: string): Promise<{ tokenId: bigint; ticket: TicketData; event: EventData | null }[]> => {
    if (!contract) return [];
    try {
      const total = await contract.getTotalTickets() as bigint;
      if (total === 0n) return [];

      const ownedIds = await contract.getTicketsByOwner(address, 0n, total - 1n) as bigint[];
      const results = await Promise.all(
        ownedIds.map(async (tokenId) => {
          const ticket = await contract.getTicketDetails(tokenId) as TicketData;
          const event = ticket ? await getEvent(ticket.eventId) : null;
          return { tokenId, ticket, event };
        })
      );
      return results;
    } catch (err) {
      console.error('getMyTickets error:', err);
      return [];
    }
  }, [contract, getEvent]);

  const getResaleListing = useCallback(async (tokenId: bigint): Promise<ResaleListing | null> => {
    if (!contract) return null;
    try {
      const listing = await contract.getResaleListing(tokenId);
      return listing as ResaleListing;
    } catch {
      return null;
    }
  }, [contract]);

  const isTicketValid = useCallback(async (tokenId: bigint, eventId: bigint): Promise<{ valid: boolean; reason: string }> => {
    if (!contract) return { valid: false, reason: 'Contract not loaded' };
    try {
      const [valid, reason] = await contract.isTicketValid(tokenId, eventId) as [boolean, string];
      return { valid, reason };
    } catch (err) {
      return { valid: false, reason: 'Error checking validity' };
    }
  }, [contract]);

  const hasRole = useCallback(async (role: string, address: string): Promise<boolean> => {
    if (!contract) return false;
    try {
      return await contract.hasRole(role, address) as boolean;
    } catch {
      return false;
    }
  }, [contract]);

  const getOrganizerRole = useCallback(async (): Promise<string> => {
    if (!contract) return '';
    return await contract.ORGANIZER_ROLE() as string;
  }, [contract]);

  const getVerifierRole = useCallback(async (): Promise<string> => {
    if (!contract) return '';
    return await contract.VERIFIER_ROLE() as string;
  }, [contract]);

  // ─── Write Functions ───────────────────────────────────────────────────────

  const createEvent = useCallback(async (
    params: {
      title: string;
      description: string;
      location: string;
      date: number;
      imageURI: string;
      category: string;
      ticketPrice: bigint;
      totalSupply: number;
      maxResaleBps: number;
    },
    onTxState: (s: TransactionState) => void
  ): Promise<bigint | null> => {
    if (!contract) { toast.error('Contract not connected'); return null; }
    setIsLoading(true);

    try {
      onTxState({ hash: null, status: 'pending', error: null });

      const tx = await contract.createEvent(
        params.title,
        params.description,
        params.location,
        params.date,
        params.imageURI,
        params.category,
        params.ticketPrice,
        params.totalSupply,
        params.maxResaleBps
      );

      onTxState({ hash: tx.hash, status: 'pending', error: null });
      toast.loading('Creating event on blockchain...', { id: 'create-event' });

      const receipt = await tx.wait();
      toast.dismiss('create-event');

      if (receipt.status === 1) {
        toast.success('Event created successfully!');
        // Parse event ID from logs
        const iface = contract.interface;
        for (const log of receipt.logs) {
          try {
            const parsed = iface.parseLog(log);
            if (parsed?.name === 'EventCreated') {
              onTxState({ hash: tx.hash, status: 'confirmed', error: null });
              return parsed.args[0] as bigint;
            }
          } catch { /* skip */ }
        }
        onTxState({ hash: tx.hash, status: 'confirmed', error: null });
        return null;
      } else {
        throw new Error('Transaction reverted');
      }
    } catch (err: unknown) {
      toast.dismiss('create-event');
      const msg = parseContractError(err);
      onTxState({ hash: null, status: 'failed', error: msg });
      toast.error(msg);
      return null;
    } finally {
      setIsLoading(false);
    }
  }, [contract]);

  const buyTicket = useCallback(async (
    eventId: bigint,
    price: bigint,
    onTxState: (s: TransactionState) => void
  ): Promise<bigint | null> => {
    if (!contract) { toast.error('Contract not connected'); return null; }
    setIsLoading(true);

    try {
      onTxState({ hash: null, status: 'pending', error: null });

      const tx = await contract.buyTicket(eventId, { value: price });
      onTxState({ hash: tx.hash, status: 'pending', error: null });
      toast.loading('Purchasing ticket...', { id: 'buy-ticket' });

      const receipt = await tx.wait();
      toast.dismiss('buy-ticket');

      if (receipt.status === 1) {
        toast.success('Ticket purchased successfully!');
        const iface = contract.interface;
        for (const log of receipt.logs) {
          try {
            const parsed = iface.parseLog(log);
            if (parsed?.name === 'TicketMinted') {
              onTxState({ hash: tx.hash, status: 'confirmed', error: null });
              return parsed.args[0] as bigint;
            }
          } catch { /* skip */ }
        }
        onTxState({ hash: tx.hash, status: 'confirmed', error: null });
        return null;
      } else {
        throw new Error('Transaction reverted');
      }
    } catch (err: unknown) {
      toast.dismiss('buy-ticket');
      const msg = parseContractError(err);
      onTxState({ hash: null, status: 'failed', error: msg });
      toast.error(msg);
      return null;
    } finally {
      setIsLoading(false);
    }
  }, [contract]);

  const listTicketForResale = useCallback(async (
    tokenId: bigint,
    price: bigint,
    onTxState: (s: TransactionState) => void
  ): Promise<boolean> => {
    if (!contract) { toast.error('Contract not connected'); return false; }
    setIsLoading(true);

    try {
      onTxState({ hash: null, status: 'pending', error: null });
      const tx = await contract.listTicketForResale(tokenId, price);
      onTxState({ hash: tx.hash, status: 'pending', error: null });
      toast.loading('Listing ticket for resale...', { id: 'list-ticket' });

      const receipt = await tx.wait();
      toast.dismiss('list-ticket');

      if (receipt.status === 1) {
        toast.success('Ticket listed for resale!');
        onTxState({ hash: tx.hash, status: 'confirmed', error: null });
        return true;
      } else {
        throw new Error('Transaction reverted');
      }
    } catch (err: unknown) {
      toast.dismiss('list-ticket');
      const msg = parseContractError(err);
      onTxState({ hash: null, status: 'failed', error: msg });
      toast.error(msg);
      return false;
    } finally {
      setIsLoading(false);
    }
  }, [contract]);

  const cancelResaleListing = useCallback(async (
    tokenId: bigint,
    onTxState: (s: TransactionState) => void
  ): Promise<boolean> => {
    if (!contract) return false;
    setIsLoading(true);

    try {
      onTxState({ hash: null, status: 'pending', error: null });
      const tx = await contract.cancelResaleListing(tokenId);
      onTxState({ hash: tx.hash, status: 'pending', error: null });
      toast.loading('Cancelling listing...', { id: 'cancel-listing' });

      const receipt = await tx.wait();
      toast.dismiss('cancel-listing');
      toast.success('Listing cancelled');
      onTxState({ hash: tx.hash, status: 'confirmed', error: null });
      return receipt.status === 1;
    } catch (err: unknown) {
      toast.dismiss('cancel-listing');
      const msg = parseContractError(err);
      onTxState({ hash: null, status: 'failed', error: msg });
      toast.error(msg);
      return false;
    } finally {
      setIsLoading(false);
    }
  }, [contract]);

  const buyResaleTicket = useCallback(async (
    tokenId: bigint,
    price: bigint,
    onTxState: (s: TransactionState) => void
  ): Promise<boolean> => {
    if (!contract) { toast.error('Contract not connected'); return false; }
    setIsLoading(true);

    try {
      onTxState({ hash: null, status: 'pending', error: null });
      const tx = await contract.buyResaleTicket(tokenId, { value: price });
      onTxState({ hash: tx.hash, status: 'pending', error: null });
      toast.loading('Purchasing resale ticket...', { id: 'buy-resale' });

      const receipt = await tx.wait();
      toast.dismiss('buy-resale');

      if (receipt.status === 1) {
        toast.success('Resale ticket purchased!');
        onTxState({ hash: tx.hash, status: 'confirmed', error: null });
        return true;
      } else {
        throw new Error('Transaction reverted');
      }
    } catch (err: unknown) {
      toast.dismiss('buy-resale');
      const msg = parseContractError(err);
      onTxState({ hash: null, status: 'failed', error: msg });
      toast.error(msg);
      return false;
    } finally {
      setIsLoading(false);
    }
  }, [contract]);

  const redeemTicket = useCallback(async (
    tokenId: bigint,
    eventId: bigint,
    onTxState: (s: TransactionState) => void
  ): Promise<boolean> => {
    if (!contract) { toast.error('Contract not connected'); return false; }
    setIsLoading(true);

    try {
      onTxState({ hash: null, status: 'pending', error: null });
      const tx = await contract.redeemTicket(tokenId, eventId);
      onTxState({ hash: tx.hash, status: 'pending', error: null });
      toast.loading('Redeeming ticket on-chain...', { id: 'redeem' });

      const receipt = await tx.wait();
      toast.dismiss('redeem');

      if (receipt.status === 1) {
        toast.success('Ticket redeemed successfully!');
        onTxState({ hash: tx.hash, status: 'confirmed', error: null });
        return true;
      } else {
        throw new Error('Redemption transaction reverted');
      }
    } catch (err: unknown) {
      toast.dismiss('redeem');
      const msg = parseContractError(err);
      onTxState({ hash: null, status: 'failed', error: msg });
      toast.error(msg);
      return false;
    } finally {
      setIsLoading(false);
    }
  }, [contract]);

  const grantVerifierRole = useCallback(async (address: string): Promise<boolean> => {
    if (!contract) return false;
    try {
      const tx = await contract.setVerifierRole(address);
      await tx.wait();
      toast.success('Verifier role granted');
      return true;
    } catch (err: unknown) {
      toast.error(parseContractError(err));
      return false;
    }
  }, [contract]);

  return {
    contract,
    contractAddress,
    isLoading,
    getEvent,
    getAllEvents,
    getTicket,
    getMyTickets,
    getResaleListing,
    isTicketValid,
    hasRole,
    getOrganizerRole,
    getVerifierRole,
    createEvent,
    buyTicket,
    listTicketForResale,
    cancelResaleListing,
    buyResaleTicket,
    redeemTicket,
    grantVerifierRole,
  };
}

function parseContractError(err: unknown): string {
  if (!err) return 'Unknown error';
  const e = err as { reason?: string; message?: string; data?: { message?: string } };

  // ethers v6 revert reasons
  if (e.reason) return e.reason;
  if (e.data?.message) return e.data.message;

  const msg = e.message || '';

  // Parse "execution reverted: <reason>"
  const match = msg.match(/execution reverted[:\s]+"?([^"]+)"?/i);
  if (match) return match[1];

  if (msg.includes('user rejected')) return 'Transaction rejected by user';
  if (msg.includes('insufficient funds')) return 'Insufficient ETH balance';
  if (msg.includes('nonce')) return 'Transaction nonce error. Please try again.';
  if (msg.length > 100) return msg.slice(0, 100) + '...';

  return msg || 'Transaction failed';
}
